    gap: 1rem;
    padding: 0.5rem;
    background: var(--light-color);
    border-radius: 4px;
}

.heartbeat-icon {
    font-size: 1.5rem;
    transition: transform 0.3s ease;
}

.heartbeat-icon.pulse {
