}

.ws-connected {
    background: var(--success-color);
    color: white;
}

.ws-disconnected {
    background: var(--danger-color);
    color: white;
}

/* Layout Styles */
.main-container {
    display: grid;
    grid-template-columns: 480px 1fr;
    min-height: calc(100vh - 80px);
    gap: 1rem;
    padding: 1rem;
}

.left-column {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
