.coordinates {
    font-family: 'Courier New', monospace;
    font-size: 10px;
    color: #ffcc00;
    letter-spacing: 0.5px;
}

/* Modern Glass Cockpit Canvas Override */
canvas {
    border: none;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}

/* Remove old PFD styling */
.pfd-container,
.pfd-main,
.pfd-center,
.pfd-info,
.pfd-status,
.pfd-telemetry,
.telemetry-row,
.telemetry-item,
.armed-status,
.flight-mode {
    display: none;
}

/* Animations for modern glass cockpit */
@keyframes pulse-armed {
    0%, 100% { 
        opacity: 1;
        transform: scale(1);
    }
    50% { 
        opacity: 0.8;
        transform: scale(1.02);
    }
}

/* Enhanced pulse animation for critical indicators */
@keyframes pulse {
    0%, 100% { 
        transform: scale(1);
        opacity: 1;
    }
    50% { 
        transform: scale(1.05);
        opacity: 0.8;
    }
}

/* G1000-Style Flight Data Panel */
.g1000-flight-data-panel {
    background: #0a0a0a;
    border: 2px solid #1e1e2e;
    border-radius: 8px;
    padding: 0.75rem;
}

.g1000-flight-data-panel h3 {
    color: #87ceeb;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
    text-align: center;
    font-weight: 500;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    border-bottom: 1px solid #2d3748;
    padding-bottom: 0.5rem;
}

.g1000-data-grid {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.data-row {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 0.5rem;
}

.data-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: rgba(10, 10, 20, 0.8);
    padding: 0.4rem;
    border-radius: 4px;
    border: 1px solid #333;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.5);
}

.data-label {
    font-family: 'Arial', sans-serif;
    font-size: 8px;
    font-weight: 500;
    color: #87ceeb;
    margin-bottom: 2px;
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

.data-value {
    font-family: 'Courier New', monospace;
    font-size: 10px;
    font-weight: 600;
    color: #00ff88;
    text-align: center;
}

/* Flight Controls Styles */
.control-groups {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.control-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.button-row {
    display: flex;
    gap: 0.5rem;
    align-items: center;
}

.takeoff-alt-row {
    display: flex;
    justify-content: center;
    margin-top: 0.5rem;
}

.alt-input {
    width: 80px;
    padding: 0.5rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 0.9rem;
    text-align: center;
}

.mode-select {
    padding: 0.5rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
}

/* Navigation Controls Styles */
.nav-inputs {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.nav-buttons {
    display: flex;
    gap: 0.5rem;
}

/* Request Controls and Audio Styles */
.request-panel h3 {
    display: none;
}

.request-buttons {
    display: flex;
    gap: 0.5rem;
}

.audio-controls {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

/* Message Log Styles */
.message-log {
    height: 150px;
    overflow-y: auto;
    padding: 0.75rem;
    background: var(--light-color);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-family: 'Courier New', monospace;
    font-size: 0.8rem;
}

.message-log .log-entry {
    margin-bottom: 0.25rem;
    padding: 0.25rem;
    border-radius: 2px;
}

.message-log .log-info {
    background: #d1ecf1;
    color: #0c5460;
}

.message-log .log-warning {
    background: #fff3cd;
    color: #856404;
}

.message-log .log-error {
    background: #f8d7da;
    color: #721c24;
}

/* Map Container Styles */
.map-container {
    position: relative;
    height: 100%;
    background: var(--panel-bg);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    overflow: hidden;
}

.map-controls {
    position: absolute;
    top: 10px;
    left: 10px;
    z-index: 1000;
    display: flex;
    gap: 0.5rem;
    background: rgba(255, 255, 255, 0.9);
    padding: 0.5rem;
    border-radius: 4px;
    backdrop-filter: blur(5px);
}

.map {
    width: 100%;
    height: 100%;
}

/* Offline Maps Panel Styles */
.offline-maps-panel {
    position: absolute;
    top: 0;
    right: -400px;
    width: 400px;
    height: 100%;
    background: var(--panel-bg);
    border-left: 1px solid var(--border-color);
    transition: right 0.3s ease;
    z-index: 2000;
    overflow-y: auto;
}

.offline-maps-panel.active {
    right: 0;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
    background: var(--primary-color);
    color: white;
}

.panel-header h3 {
    margin: 0;
    color: white;
}

.close-btn {
    background: none;
    border: none;
    color: white;
    font-size: 1.5rem;
    cursor: pointer;
    padding: 0;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
}

.close-btn:hover {
    background: rgba(255, 255, 255, 0.2);
}

.panel-content {
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.internet-status {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem;
    background: var(--light-color);
    border-radius: 4px;
}

.internet-status.online {
    background: #d4edda;
    color: #155724;
}

.internet-status.offline {
    background: #f8d7da;
    color: #721c24;
}

.coord-inputs {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.input-row {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.input-row label {
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--text-muted);
}

.input-row input {
    padding: 0.5rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 0.9rem;
}

.zoom-section {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.5rem;
    margin: 1rem 0;
}

.map-types {
    margin: 1rem 0;
}

.map-types label {
    display: block;
    margin-bottom: 0.5rem;
    cursor: pointer;
}

.download-info {
    padding: 1rem;
    background: var(--light-color);
    border-radius: 4px;
    margin: 1rem 0;
}

.download-controls {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.progress-bar {
    width: 100%;
    height: 20px;
    background: var(--light-color);
    border-radius: 10px;
    overflow: hidden;
    margin-bottom: 0.5rem;
}

.progress-fill {
    height: 100%;
    background: var(--primary-color);
    width: 0%;
    transition: width 0.3s ease;
}

.cache-stats {
    background: var(--light-color);
    padding: 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

.cache-stats p {
    display: flex;
    justify-content: space-between;
    margin-bottom: 0.5rem;
}

.tips-section ul {
    padding-left: 1.5rem;
}

.tips-section li {
    margin-bottom: 0.5rem;
    color: var(--text-muted);
    font-size: 0.9rem;
}

/* Modal Styles */
.modal {
    display: none;
    position: fixed;
    z-index: 3000;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(3px);
}

.modal.active {
    display: flex;
    align-items: center;
    justify-content: center;
}

.modal-content {
    background: var(--panel-bg);
    padding: 2rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
}

.modal-content h3 {
    margin-bottom: 1rem;
    color: var(--danger-color);
}

.modal-content p {
    margin-bottom: 1.5rem;
    color: var(--text-muted);
}

.modal-buttons {
    display: flex;
    gap: 0.5rem;
    justify-content: flex-end;
}

/* Responsive Design */
@media (max-width: 1200px) {
    .main-container {
        grid-template-columns: 420px 1fr;
    }

    .right-column {
        width: 100%;
    }
}

@media (max-width: 768px) {
    .main-container {
        grid-template-columns: 1fr;
        grid-template-rows: auto 1fr;
        height: auto;
        min-height: calc(100vh - 80px);
    }

    .left-column {
        max-height: none;
        order: 2;
    }

    .right-column {
        order: 1;
        height: 350px;
        width: 100%;
    }

    .main-header {
        padding: 0.75rem 1rem;
    }

    .main-header h1 {
        font-size: 1.4rem;
    }

    .header-controls {
        gap: 0.5rem;
    }

    .connection-inputs {
        grid-template-columns: 1fr;
    }

    .control-groups {
        gap: 1rem;
    }

    .button-row {
        flex-wrap: wrap;
    }

    .offline-maps-panel {
        width: 100%;
        right: -100%;
    }
}

/* Animation Classes */
.fade-in {
    animation: fadeIn 0.3s ease-in;
}

.pulse {
    animation: pulse 0.3s ease-in-out;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes pulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.1); }
}

/* Utility Classes */
.text-center {
    text-align: center;
}

.text-muted {
    color: var(--text-muted);
}

.mt-1 { margin-top: 0.5rem; }
.mb-1 { margin-bottom: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mb-2 { margin-bottom: 1rem; }

.d-none {
    display: none !important;
}

.d-block {
    display: block !important;
}

.d-flex {
    display: flex !important;
}

/* Additional Message Log Styles */
.log-success {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.log-debug {
    background: #f8f9fa;
    color: #495057;
    border: 1px solid #dee2e6;
}

.log-entry {
    padding: 0.25rem 0.5rem;
    border-radius: 3px;
    margin-bottom: 0.25rem;
    font-size: 0.85rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.log-time {
    color: var(--text-muted);
    font-size: 0.8rem;
    min-width: 70px;
}

.log-icon {
    min-width: 20px;
    text-align: center;
}

.log-text {
    flex: 1;
    word-break: break-word;
}

