    gap: 0.75rem;
}

.button-row {
    display: flex;
    gap: 0.5rem;
    align-items: center;
}

.takeoff-alt-row {
    display: flex;
    justify-content: center;
    margin-top: 0.5rem;
}

.alt-input {
    width: 80px;
