}

.g1000-data-grid {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.data-row {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 0.5rem;
}

.data-item {
