/* WebGCS Main Stylesheet */
:root {
    --primary-color: #007bff;
    --secondary-color: #6c757d;
    --success-color: #28a745;
    --danger-color: #dc3545;
    --warning-color: #ffc107;
    --info-color: #17a2b8;
    --light-color: #f8f9fa;
    --dark-color: #343a40;
    --background-color: #f0f2f5;
    --panel-bg: #ffffff;
    --border-color: #dee2e6;
    --text-color: #212529;
    --text-muted: #6c757d;
}

/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background-color: var(--background-color);
    color: var(--text-color);
    line-height: 1.6;
    font-size: 16px; /* Base font size increased */
}

/* Header Styles */
.main-header {
    background: var(--dark-color);
    color: white;
    padding: 1rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 3px solid var(--primary-color);
}

.main-header h1 {
    font-size: 2.2rem;
    font-weight: 600;
}

.header-controls {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.dump-link {
    background: var(--info-color);
    color: white;
    padding: 0.6rem 1.2rem;
    text-decoration: none;
    border-radius: 4px;
    font-size: 1.1rem;
    transition: background-color 0.3s;
}

.dump-link:hover {
    background: #138496;
}

.websocket-status {
    padding: 0.6rem 1.2rem;
    border-radius: 4px;
    font-size: 1.1rem;
    font-weight: 500;
}

.ws-connected {
    background: var(--success-color);
    color: white;
}

.ws-disconnected {
    background: var(--danger-color);
    color: white;
}

/* Layout Styles */
.main-container {
    display: grid;
    grid-template-columns: 480px 1fr;
    min-height: calc(100vh - 80px);
    gap: 1rem;
    padding: 1rem;
}

.left-column {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    overflow-y: visible;
    padding-right: 0.5rem;
}

.right-column {
    position: relative;
