    border-radius: 4px;
    font-size: 1.1rem;
    transition: background-color 0.3s;
}

.dump-link:hover {
    background: #138496;
}

.websocket-status {
    padding: 0.6rem 1.2rem;
    border-radius: 4px;
    font-size: 1.1rem;
