}

/* Layout Styles */
.main-container {
    display: grid;
    grid-template-columns: 480px 1fr;
    min-height: calc(100vh - 80px);
    gap: 1rem;
    padding: 1rem;
}

.left-column {
    display: flex;
    flex-direction: column;
