    gap: 0.5rem;
}

.log-time {
    color: var(--text-muted);
    font-size: 0.8rem;
    min-width: 70px;
}

.log-icon {
    min-width: 20px;
    text-align: center;
}

.log-text {
    flex: 1;
    word-break: break-word;
}

