    font-weight: 600;
    border-bottom: 2px solid var(--primary-color);
    padding-bottom: 0.4rem;
}

.panel h4 {
    color: var(--text-color);
    margin-bottom: 0.75rem;
    font-size: 1.2rem;
    font-weight: 500;
}

/* Connection Management Styles */
