/* Modern Glass Cockpit Canvas Override */
canvas {
    border: none;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}

/* Remove old PFD styling */
.pfd-container,
.pfd-main,
.pfd-center,
.pfd-info,
.pfd-status,
.pfd-telemetry,
.telemetry-row,
.telemetry-item,
.armed-status,
.flight-mode {
    display: none;
}

/* Animations for modern glass cockpit */
@keyframes pulse-armed {
    0%, 100% { 
        opacity: 1;
        transform: scale(1);
    }
    50% { 
        opacity: 0.8;
        transform: scale(1.02);
    }
}

/* Enhanced pulse animation for critical indicators */
@keyframes pulse {
    0%, 100% { 
        transform: scale(1);
        opacity: 1;
    }
    50% { 
        transform: scale(1.05);
        opacity: 0.8;
    }
}

/* G1000-Style Flight Data Panel */
.g1000-flight-data-panel {
    background: #0a0a0a;
