    font-weight: 500;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    border-bottom: 1px solid #2d3748;
    padding-bottom: 0.5rem;
}

.g1000-data-grid {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.data-row {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 0.5rem;
}

.data-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: rgba(10, 10, 20, 0.8);
    padding: 0.4rem;
    border-radius: 4px;
