/* Flight Controls Styles */
.control-groups {
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
}

.control-group {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.button-row {
    display: flex;
    gap: 0.3rem;
    align-items: center;
}

.takeoff-alt-row {
    display: flex;
    justify-content: center;
    margin-top: 0.5rem;
}

.alt-input {
    width: 80px;
    padding: 0.7rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 1.1rem;
    text-align: center;
}

.mode-select {
    padding: 0.7rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 1.1rem;
