    border: 1px solid #f5c6cb;
}

.status-indicator.connecting {
    background: #d1ecf1;
    color: #0c5460;
    border: 1px solid #b8daff;
}

.status-indicator.backend-connected {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.heartbeat-section {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 0.5rem;
    background: var(--light-color);
    border-radius: 4px;
}

.heartbeat-icon {
    font-size: 1.5rem;
