}

.input-group {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.input-group label {
    font-size: 1.1rem;
    font-weight: 500;
    color: var(--text-muted);
}

.input-group input {
    padding: 0.7rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 1.1rem;
}

.connection-buttons {
    display: flex;
    gap: 0.5rem;
}

/* Button Styles */
.btn {
    padding: 0.8rem 1.3rem;
    border: none;
    border-radius: 4px;
    font-size: 1.2rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s ease;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    white-space: nowrap;
}

.btn:disabled {
    opacity: 0.6;
