}

.btn-disconnect {
    background: var(--danger-color);
    color: white;
}

/* Modern Glass Cockpit Primary Flight Display */
.glass-pfd-panel {
    background: #0a0a0a;
    border: 2px solid #1e1e2e;
    border-radius: 12px;
    padding: 0.75rem;
}

.glass-pfd-panel h3 {
