.modal-content h3 {
    margin-bottom: 1rem;
    color: var(--danger-color);
}

.modal-content p {
    margin-bottom: 1.5rem;
    color: var(--text-muted);
}

.modal-buttons {
    display: flex;
    gap: 0.3rem;
    justify-content: flex-end;
}

/* Responsive Design */
@media (max-width: 1200px) {
    .main-container {
        grid-template-columns: 420px 1fr;
    }

    .right-column {
        width: 100%;
    }
}

@media (max-width: 768px) {
    .main-container {
        grid-template-columns: 1fr;
        grid-template-rows: auto 1fr;
        height: auto;
        min-height: calc(100vh - 80px);
    }

    .left-column {
        max-height: none;
        order: 2;
    }

    .right-column {
        order: 1;
        height: 350px;
        width: 100%;
    }

    .main-header {
        padding: 0.75rem 1rem;
    }

    .main-header h1 {
        font-size: 1.4rem;
    }

    .header-controls {
        gap: 0.5rem;
    }

    .connection-inputs {
        grid-template-columns: 1fr;
    }

    .control-groups {
        gap: 1rem;
    }

    .button-row {
        flex-wrap: wrap;
    }

    .offline-maps-panel {
        width: 100%;
        right: -100%;
    }
}

/* Animation Classes */
.fade-in {
    animation: fadeIn 0.3s ease-in;
}

.pulse {
    animation: pulse 0.3s ease-in-out;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes pulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.1); }
}

/* Utility Classes */
.text-center {
    text-align: center;
}

.text-muted {
    color: var(--text-muted);
}

.mt-1 { margin-top: 0.5rem; }
.mb-1 { margin-bottom: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mb-2 { margin-bottom: 1rem; }

.d-none {
    display: none !important;
}

.d-block {
    display: block !important;
}

.d-flex {
    display: flex !important;
}

/* Additional Message Log Styles */
.log-success {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.log-debug {
    background: #f8f9fa;
    color: #495057;
    border: 1px solid #dee2e6;
}

.log-entry {
    padding: 0.3rem 0.6rem;
    border-radius: 3px;
    margin-bottom: 0.25rem;
    font-size: 1rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.log-time {
    color: var(--text-muted);
    font-size: 0.95rem;
    min-width: 70px;
}

.log-icon {
    min-width: 20px;
    text-align: center;
}

.log-text {
    flex: 1;
    word-break: break-word;
}

