}

.modal.active {
    display: flex;
    align-items: center;
    justify-content: center;
}

.modal-content {
    background: var(--panel-bg);
    padding: 2rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
}

.modal-content h3 {
    margin-bottom: 1rem;
    color: var(--danger-color);
}

.modal-content p {
    margin-bottom: 1.5rem;
    color: var(--text-muted);
}

.modal-buttons {
    display: flex;
    gap: 0.3rem;
    justify-content: flex-end;
}

/* Responsive Design */
@media (max-width: 1200px) {
    .main-container {
        grid-template-columns: 420px 1fr;
    }

    .right-column {
        width: 100%;
    }
}

@media (max-width: 768px) {
    .main-container {
        grid-template-columns: 1fr;
        grid-template-rows: auto 1fr;
        height: auto;
        min-height: calc(100vh - 80px);
    }

    .left-column {
        max-height: none;
        order: 2;
    }

    .right-column {
        order: 1;
        height: 350px;
        width: 100%;
    }

    .main-header {
        padding: 0.75rem 1rem;
