    border: 1px solid #c3e6cb;
}

.status-indicator.disconnected {
    background: #f8d7da;
    color: #721c24;
    border: 1px solid #f5c6cb;
}

.status-indicator.connecting {
    background: #d1ecf1;
    color: #0c5460;
    border: 1px solid #b8daff;
}

.status-indicator.backend-connected {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.heartbeat-section {
    display: flex;
