}

.g1000-data-grid {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.data-row {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 0.5rem;
}

.data-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: rgba(10, 10, 20, 0.8);
    padding: 0.4rem;
    border-radius: 4px;
    border: 1px solid #333;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.5);
}

.data-label {
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    font-weight: 500;
    color: #87ceeb;
    margin-bottom: 2px;
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

.data-value {
    font-family: 'Courier New', monospace;
    font-size: 13px;
    font-weight: 600;
    color: #00ff88;
    text-align: center;
}

/* Flight Controls Styles */
.control-groups {
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
}

.control-group {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.button-row {
    display: flex;
    gap: 0.3rem;
    align-items: center;
}

.takeoff-alt-row {
    display: flex;
    justify-content: center;
    margin-top: 0.5rem;
}

.alt-input {
    width: 80px;
    padding: 0.7rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 1.1rem;
    text-align: center;
}

.mode-select {
    padding: 0.7rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 1.1rem;
    margin-bottom: 0.3rem;
}

/* Navigation Controls Styles */
.nav-inputs {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.nav-buttons {
    display: flex;
    gap: 0.3rem;
}

/* Request Controls and Audio Styles */
.request-panel h3 {
    display: none;
}

.request-buttons {
    display: flex;
    gap: 0.3rem;
}

.audio-controls {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
